B.cDr=s([B.bfD],t.I)
B.bCD=new A.h("Severe infections (PO or IV):",B.cDr,null)
B.b_1=new A.b("Child: 2\u20134 mg/kg/24 hr PO once daily",!1)
B.e0R=s([B.b_1],t.I)
B.bBG=new A.h("Urinary tract infection (UTI) prophylaxis:",B.e0R,null)
