B.cD3=s(["Injection (single-dose, preservative-free vials): 2000, 3000, 4000, 10,000, 40,000 U/mL (1 mL); contains phenylalanine","Injection (multidose vials): 10,000 U/mL (2 mL), 20,000 U/mL (1 mL); contains 1% benzyl alcohol","All dosage forms contain 2.5 mg albumin per 1 mL.","NOTE: Epoetin alfa-epbx (Retacrit) is a biosimilar product."],t.s)
B.aHW=new A.b("SC/IV (IV preferred for hemodialysis patients)",!1)
B.CM=new A.b("Initial dose:",!0)
B.blZ=new A.b("Child and adolescent \u226416 yr: Start at 50 U/kg/dose 3 times per week. Reported dosage range for children (3 mo\u201320 yr) not requiring dialysis: 50\u2013250 U/kg/dose 3 times per week. Reported dosage range for children receiving hemodialysis: 50\u2013450 U/kg/dose 2\u20133 times per week.",!1)
B.aG8=new A.b("Adolescent >16 yr and adult: Start at 50\u2013100 U/kg/dose 3 times per week",!1)
B.az0=new A.b("Maintenance dose: Dose is individualized to achieve and maintain the lowest Hgb level sufficient to avoid transfusions and not to exceed the following levels:",!1)
B.asC=new A.b("Child \u226416 yr (receiving or not receiving dialysis): 12 g/dL",!1)
B.aYX=new A.b("Adolescent >16 yr and adult:",!1)
B.aC9=new A.b("Receiving dialysis: 11 g/dL",!1)
B.b9d=new A.b("Not receiving dialysis: 10 g/dL",!1)
B.dLZ=s([B.aHW,B.CM,B.blZ,B.aG8,B.az0,B.asC,B.aYX,B.aC9,B.b9d],t.I)
B.bwP=new A.h("Anemia in chronic renal failure (see remarks for dosage adjustment and withholding therapy):",B.dLZ,null)
B.b2a=new A.b("Child (5\u201318 yr): Start at 600 U/kg (max. dose: 40,000 U) IV once weekly",!1)
B.bhu=new A.b("Adult: Start at 40,000 U SC once every week or 150 U/kg/dose SC 3 times per week",!1)
B.aKG=new A.b("Increasing doses (if needed):",!0)
B.aUX=new A.b("Weekly dosing regimen: If no increase in Hgb >1 g/dL and Hgb remains <10 g/dL after initial 4 wk of therapy:",!0)
B.aYf=new A.b("Child: Increase dose to 900 U/kg/dose IV (max. dose: 60,000 U) once weekly",!1)
B.aTB=new A.b("Adult: 60,000 U SC once weekly",!1)
B.bco=new A.b("Three-times-a-week dosing regimen (adult): If no increase in Hgb >1 g/dL and Hgb remains <10 g/dL after initial 4 wk of therapy, increase dosage to 300 U/kg/dose 3 times per week.",!1)
B.aTI=new A.b("For all ages, discontinue use after 8 wk of therapy if transfusions are still required or no hemoglobin response is observed.",!1)
B.dad=s([B.CM,B.b2a,B.bhu,B.aKG,B.aUX,B.aYf,B.aTB,B.bco,B.aTI],t.I)
B.bpz=new A.h("Anemia in cancer (use until chemotherapy is completed; see remarks for dosage reduction and withholding therapy):",B.dad,null)
B.aGV=new A.b("250 U/kg/dose SC 3 times per wk \xd7 10 doses; alternatively, 200\u2013400 U/kg/dose IV/SC 3\u20135 times per week for 2\u20136 wk (total dose per week is 600\u20131400 U/kg). Administer with supplemental iron at 3\u20136 mg elemental iron/kg/24 hr.",!1)
