B.b8S=new A.b("Infant \u22651 mo and child (see remarks):",!0)
B.bjr=new A.b("Mild/moderate infections: 100\u2013200 mg/kg/24 hr \xf7 Q6 hr IM/IV; max. dose: 8 g ampicillin/24 hr",!1)
B.aXj=new A.b("Meningitis/severe infections: 200\u2013400 mg/kg/24 hr \xf7 Q4\u20136 hr IM/IV; max. dose: 8 g ampicillin/24 hr",!1)
B.b_L=new A.b("Adult: 1\u20132 g Q6\u20138 hr IM/IV; max. dose: 8 g ampicillin/24 hr",!1)
