B.dP6=s([B.bdC,B.aYr,B.aIK,B.br,B.azR,B.aFM,B.axQ,B.bfm,B.bit,B.bhF,B.bi8,B.b8X,B.Oh,B.aWz,B.aLX,B.bg9,B.Oh,B.bbo,B.aRC,B.aOs,B.aKA],t.I)
