B.bfQ=new A.b("\u226411 kg: 150\u2013250 mg/24 hr \xf7 BID",!1)
B.bc2=new A.b("12\u201322 kg: 200\u2013300 mg/24 hr \xf7 BID",!1)
B.baJ=new A.b("23\u201331 kg: 200\u2013350 mg/24 hr \xf7 BID",!1)
